// Reports — the center of the application. Every report generated by the
// Enterprise Brain, categorized for a Product Manager: Daily, Weekly,
// Monthly, Product, Merchant, Bank, Failure Analysis, Growth Analysis,
// Executive. Each report shows its summary, findings, evidence,
// recommendations, linked decisions, related products, trend, and export.
import { useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { api } from '../api/client'
import { AsyncSection, Badge, PageHeader, PanelEmpty, useAsync } from '../components/ui'
import { ExportMenu, TrendRow } from '../components/premium'

const CATEGORIES = [
  'Daily Reports', 'Weekly Reports', 'Monthly Reports', 'Product Reports',
  'Merchant Reports', 'Bank Reports', 'Failure Analysis', 'Growth Analysis',
  'Executive Reports',
]

function growthFilter(r) {
  const t = `${r.title} ${r.summary}`.toLowerCase()
  return t.includes('growth') || t.includes('adoption')
}

// "Executive Reports" aggregates the weekly + monthly executive summaries —
// the backend categorizes each report once (Weekly vs Monthly) for its own
// tab, and this view re-groups them for the exec-level rollup.
function categoryFilter(r, tab) {
  if (tab === 'Growth Analysis') return growthFilter(r)
  if (tab === 'Executive Reports') return r.category === 'Weekly Reports' || r.category === 'Monthly Reports'
  return r.category === tab
}

function ReportDetail({ r, onClose }) {
  const navigate = useNavigate()
  const [draft, setDraft] = useState(null)
  const [busy, setBusy] = useState(false)

  // Phase 2 #16 — generate an email grounded in *this* report's own summary,
  // recommendations and evidence (never a generic template).
  function generateEmail() {
    setBusy(true)
    api.commDraft('management_update', {
      entity: r.related_products?.[0] || r.title,
      recipient_name: 'Leadership', summary: r.summary || '',
      actions: (r.recommendations || '').split('\n').map((s) => s.trim()).filter(Boolean).slice(0, 5),
      evidence: (r.supporting_evidence?.length ? r.supporting_evidence : [r.report_id]).slice(0, 6),
      sender_name: 'Product Operations',
    }).then(setDraft).catch(() => setDraft(null)).finally(() => setBusy(false))
  }

  return (
    <div className="fixed inset-0 z-50 flex justify-end bg-black/50" onClick={onClose}>
      <div className="w-full max-w-xl h-full bg-surface-raised border-l border-surface-border overflow-y-auto p-6"
           onClick={(e) => e.stopPropagation()}>
        <div className="flex items-start justify-between gap-3">
          <div>
            <Badge tone="accent">{r.category}</Badge>
            <h2 className="text-lg font-bold text-slate-100 mt-2">{r.title}</h2>
            <div className="text-xs text-slate-500 mt-1">Week {r.week} · {r.report_id}</div>
          </div>
          <button onClick={onClose} className="text-slate-500 hover:text-slate-200">✕</button>
        </div>

        <div className="flex flex-wrap gap-2 mt-4">
          <button className="btn-ghost" onClick={() => navigate(`/assistant?q=${encodeURIComponent(`Discuss report ${r.report_id}: ${r.title}`)}`)}>💬 Discuss</button>
          <button className="btn-ghost" onClick={generateEmail} disabled={busy}>{busy ? 'Drafting…' : '✉ Generate email'}</button>
        </div>

        {draft && (
          <div className="mt-4 card-pad border-accent/40">
            <div className="flex items-center justify-between mb-2">
              <div className="text-sm font-medium text-slate-200">Draft email — grounded in this report</div>
              <button className="btn-quiet" onClick={() => setDraft(null)}>Dismiss</button>
            </div>
            <div className="text-[11px] uppercase tracking-wide text-slate-500">Subject</div>
            <div className="text-sm font-medium text-slate-200 mb-2">{draft.subject}</div>
            <pre className="text-sm text-slate-300 whitespace-pre-wrap font-sans">{draft.body}</pre>
            <div className="text-[11px] text-slate-500 mt-2">Draft only — an actual send goes through approval.</div>
          </div>
        )}

        <section className="mt-5">
          <div className="h-sub mb-1.5">AI Summary</div>
          <p className="text-sm text-slate-300 leading-relaxed">{r.summary || '—'}</p>
        </section>

        {r.key_findings && (
          <section className="mt-5">
            <div className="h-sub mb-1.5">Key Findings</div>
            <p className="text-sm text-slate-300 leading-relaxed whitespace-pre-wrap">{r.key_findings}</p>
          </section>
        )}

        {r.recommendations && (
          <section className="mt-5">
            <div className="h-sub mb-1.5">Recommendations</div>
            <p className="text-sm text-slate-300 leading-relaxed whitespace-pre-wrap">{r.recommendations}</p>
          </section>
        )}

        {r.trend && (
          <section className="mt-5 card-pad">
            <div className="h-sub mb-2">Trend — Success Rate</div>
            <TrendRow trend={r.trend} unit="%" />
          </section>
        )}

        {r.related_products?.length > 0 && (
          <section className="mt-5">
            <div className="h-sub mb-1.5">Related Products</div>
            <div className="flex flex-wrap gap-1.5">
              {r.related_products.map((p) => <Badge key={p}>{p}</Badge>)}
            </div>
          </section>
        )}

        {r.linked_decisions?.length > 0 && (
          <section className="mt-5">
            <div className="h-sub mb-1.5">Linked Decisions</div>
            <div className="flex flex-wrap gap-1.5">
              {r.linked_decisions.map((d) => <Badge key={d} tone="info">{d}</Badge>)}
            </div>
          </section>
        )}

        {r.supporting_evidence?.length > 0 && (
          <section className="mt-5">
            <div className="h-sub mb-1.5">Supporting Evidence</div>
            <ul className="text-xs text-slate-500 space-y-1">
              {r.supporting_evidence.map((e) => <li key={e}>• {e}</li>)}
            </ul>
          </section>
        )}

        <div className="mt-6 pt-4 border-t border-surface-border">
          <ExportMenu filename={r.report_id} json={r} />
        </div>
      </div>
    </div>
  )
}

function ReportCard({ r, onOpen }) {
  return (
    <button onClick={() => onOpen(r)} className="card-pad card-hover text-left block w-full">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <div className="text-sm font-medium text-slate-200 truncate">{r.title}</div>
          <div className="text-xs text-slate-500 mt-1">Week {r.week} · {r.report_id}</div>
        </div>
        <Badge>{r.category}</Badge>
      </div>
      {r.summary && <p className="text-xs text-slate-500 mt-2.5 line-clamp-2">{r.summary}</p>}
    </button>
  )
}

export default function ReportsHub() {
  const [tab, setTab] = useState(CATEGORIES[0])
  const [q, setQ] = useState('')
  const [open, setOpen] = useState(null)
  const state = useAsync(() => api.executiveReports().catch(() => ({ reports: [] })), [])

  return (
    <>
      <PageHeader title="Reports" subtitle="Daily, weekly, monthly, and executive reports — with evidence and recommendations">
        <input className="input max-w-xs" placeholder="Search reports…" value={q} onChange={(e) => setQ(e.target.value)} />
      </PageHeader>
      <AsyncSection state={state} empty="No reports yet.">
        {({ reports }) => (
          <ReportList reports={reports || []} tab={tab} setTab={setTab} q={q} open={open} setOpen={setOpen} />
        )}
      </AsyncSection>
    </>
  )
}

function ReportList({ reports, tab, setTab, q, open, setOpen }) {
  const filtered = useMemo(() => {
    let list = reports.filter((r) => categoryFilter(r, tab))
    const needle = q.trim().toLowerCase()
    if (needle) list = list.filter((r) => r.title.toLowerCase().includes(needle))
    return list
  }, [reports, tab, q])

  return (
    <div className="space-y-4">
      <div className="flex gap-1 border-b border-surface-border mb-2 overflow-x-auto">
        {CATEGORIES.map((c) => {
          const count = reports.filter((r) => categoryFilter(r, c)).length
          return (
            <button key={c} onClick={() => setTab(c)}
                    className={`px-3 py-2 text-sm whitespace-nowrap border-b-2 -mb-px transition-colors ${
                      tab === c ? 'border-accent text-slate-100' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
              {c}<span className="ml-1.5 text-xs text-slate-500 tabular-nums">{count}</span>
            </button>
          )
        })}
      </div>
      {filtered.length === 0 ? <PanelEmpty text="No reports in this category." /> : (
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {filtered.map((r) => <ReportCard key={r.report_id} r={r} onOpen={setOpen} />)}
        </div>
      )}
      {open && <ReportDetail r={open} onClose={() => setOpen(null)} />}
    </div>
  )
}
